import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlLinkComponent } from '@domg-wc/components/atom';
import { VlProzaMessage } from '@domg-wc/components/block';

registerWebComponents([VlProzaMessage, VlButtonComponent, VlLinkComponent]);

// vl-proza-message haalt het bericht op bij proza/domein/{domain}/{code}, relatief tov de huidige url of achter
// base-url, tenzij vl-proza-message-preloader het domein al ophaalde. Per domein vraagt het ook één keer
// proza/domein/{domain}/toegelatenoperaties op. In Storybook antwoordt een mock voor mockdomain.
// Een bericht met een block element (bv. een div) krijgt vanzelf het attribuut block.

import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlLinkComponent } from '@domg-wc/components/atom';
import { VlProzaMessage } from '@domg-wc/components/block';

registerWebComponents([VlProzaMessage, VlButtonComponent, VlLinkComponent]);

// Er is geen attribuut om een bericht editeerbaar te maken: de backend beslist. Geeft
// proza/domein/{domain}/toegelatenoperaties voor de huidige gebruiker update: true terug, dan toont
// vl-proza-message naast het bericht een edit-knop, die /proza/domeinen/{domain}/codes/{code} in een nieuw tabblad
// opent, en een refresh-knop, die het bericht opnieuw ophaalt zonder de cache van de browser.
